{
  "name": "windsurf-oauth-opencode",
  "version": "0.1.8",
  "description": "OpenCode plugin for Windsurf browser auth and cloud model access.",
  "license": "MIT",
  "type": "module",
  "main": "./dist/index.js",
  "module": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js",
      "default": "./dist/index.js"
    }
  },
  "bin": {
    "windsurf-oauth-opencode": "bin/setup.js"
  },
  "files": [
    "dist",
    "bin/setup.js",
    "README.md",
    "package.json"
  ],
  "scripts": {
    "build": "rm -rf dist && tsc -p tsconfig.json && bun build ./bin/setup.ts --target=node --format=esm --outfile=bin/setup.js --external=jsonc-parser",
    "bench": "bun scripts/bench.ts",
    "test": "bun test/smoke.ts",
    "test:live": "bun test/live.ts",
    "prepack": "npm run build",
    "prepublishOnly": "npm run build && npm run test"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/jaredboynton/windsurf-oauth-opencode.git"
  },
  "homepage": "https://github.com/jaredboynton/windsurf-oauth-opencode#readme",
  "bugs": {
    "url": "https://github.com/jaredboynton/windsurf-oauth-opencode/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "windsurf",
    "oauth",
    "openai-compatible"
  ],
  "engines": {
    "node": ">=18"
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.2.27",
    "jsonc-parser": "^3.3.1",
    "zod": "^3.24.0"
  },
  "devDependencies": {
    "@types/bun": "^1.3.11",
    "typescript": "^5.9.3"
  }
}
